    const OBSERVED_CHARGE_HEADROOM_W = 100;
    const UNDERUSE_DETECTION_DELAY_MS = 10000;
    const UNDERUSE_MARGIN_W = 100;

    function isReading(value) {
        if (value === null || value === undefined || value === "") return false;
