        const soc = Number(battery?.soc);
        const socMax = Number(battery?.soc_max);
        const socMin = Number(battery?.soc_min);

        if (mode === "charge" && hasSoc && isReading(battery?.soc_max) && soc >= socMax) {
            return 0;
        }
        if (mode === "discharge" && hasSoc && isReading(battery?.soc_min) && soc <= socMin) {
            return 0;
        }
        if (mode !== "charge") {
            return requestedPower;
        }

        const observedPower = getObservedModePower(battery);
        const lastCommand = getLastCommand(battery);
